SELECT ?z ?ts ?unit ?qk WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?l .
  FILTER(?l="Core_top")
  ?z ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
  OPTIONAL { ?ext brick:hasUnits ?unit . ?ext ?p ?qk . }
}

SELECT ?z ?l ?pred WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?l .
  FILTER(CONTAINS(LCASE(?l), "core"))
}

